local Action = require(script.Parent.Action)
local View = require(script.Parent.Parent.Parent.View)
local module = {}
module.__index = module

function module.new(inputScript: ModuleScript, adapter)
    local self = require(inputScript)
    self._adapter = adapter

    for i, v in pairs(module) do
        self[i] = v
    end

    if self.Sinked == nil then
        self.Sinked = true
    end
    self._activated = false
    self._actions = {}

    self._dpadListActions = {}
    self._thumbstickListActions = {}

    self = View.new(inputScript)

    return self
end

function module:SetSinked(sinked: boolean)
    self.Sinked = sinked
end

function module:Activate(toggle: boolean)
    if toggle == nil then
        toggle = true
    end
    self:SetActivated(toggle)
end

function module:Deactivate()
    self:SetActivated(false)
end

function module:SetActivated(activated)
    assert(type(activated) == "boolean", "activated must be a boolean")
    self._activated = activated
    if activated then
        self._adapter:Push(self)
    else
        self._adapter:Remove(self)
    end
end

function module:BindAction(cmdName, key, ...)
    local cmd = nil
    if typeof(cmdName) == "function" then
        cmd = {
            Execute = cmdName,
            CanExecute = function()
                return true
            end
        }
    elseif typeof(cmdName) == "string" then
        cmd = self.DataContext:_getCommand(cmdName)
    end
    if cmd then
        local action = Action.new(cmd, key, ...)
        table.insert(self._actions, action)
        task.spawn(function()
            wait()
            if self._activated then
                self._adapter:_reloadInputs()
            end
        end)
        return action
    end
end

function module:UnbindAction(keyOrName)
    if typeof(keyOrName) == "string" then
        self:_unbindActionWithName(keyOrName)
    else
        self:_unbindActionWithKey(keyOrName)
    end
    if self._activated then
        self._adapter:_reloadInputs()
    end
end

function module:_unbindActionWithName(name)
    for i, action in pairs(self._actions) do
        if action.Name == name then
            action:_setIconShow(false)
            table.remove(self._actions, i)
            break
        end
    end
end

function module:_unbindActionWithKey(key)
    for i, action in pairs(self._actions) do
        local k = action.Key
        if typeof(key) == "table" then
            local t = {}
            for _, v in pairs(key) do
                table.insert(t, v.Name)
            end
            k = table.concat(t, "+")
        else
            k = key.Name
        end
        if k == action.Key then
            action:_setIconShow(false)
            table.remove(self._actions, i)
        end
    end
end

function module:BindListThumbstick1Action(cmdName: string, listFrame: GuiObject, startObj: GuiObject | nil, func: (GuiObject) -> ())
    local key = Enum.KeyCode.Thumbstick1
    local cmd = nil
    if typeof(cmdName) == "function" then
        cmd = {
            Execute = cmdName,
            CanExecute = function(...)
                return true
            end
        }
    elseif typeof(cmdName) == "string" then
        cmd = self.DataContext:_getCommand(cmdName)
    end
    if cmd then

        local function getChildren()
            local children = {}
            for i, v in pairs(listFrame:GetChildren()) do
                if v:IsA("GuiObject") and v.Visible then
                    table.insert(children, v)
                end
            end
            table.sort(children, function(a, b)
                return a.LayoutOrder < b.LayoutOrder
            end)
            return children
        end

        local isScrollingFrame = listFrame:IsA("ScrollingFrame")
        local action = Action.new(cmd, key)
        action:Named("_ListThumbstick1Action")
        -- FIX ME: 需要删除event
        action.KeyEvent = Instance.new("BindableEvent")
        table.insert(self._actions, action)

        local cellCountX = 1
        local cellCountY = 1
        local cellPaddingX = 0
        local cellPaddingY = 0
        
        local children = getChildren()
        local cur = startObj or children[1]

        if listFrame:FindFirstChildWhichIsA("UIGridLayout") then
            local layout = listFrame:FindFirstChildWhichIsA("UIGridLayout")
            cellCountX = layout.AbsoluteCellCount.X
            cellCountY = layout.AbsoluteCellCount.Y
            cellPaddingX = layout.CellPadding.X.Offset + layout.CellPadding.X.Scale * listFrame.AbsoluteSize.X
            cellPaddingY = layout.CellPadding.Y.Offset + layout.CellPadding.Y.Scale * listFrame.AbsoluteSize.Y
        elseif listFrame:FindFirstChildWhichIsA("UIListLayout") then
            cellCountX = 1
            cellCountY = #children
            local layout = listFrame:FindFirstChildWhichIsA("UIListLayout")
            cellPaddingX = layout.Padding.Offset + layout.Padding.Scale * listFrame.AbsoluteSize.X
            cellPaddingY = layout.Padding.Offset + layout.Padding.Scale * listFrame.AbsoluteSize.Y
        end

        local function getItem(direction)
            local children = getChildren()
            local curIdx = table.find(children, cur)
            local temp = curIdx
            if direction == "up" then
                if curIdx - cellCountX > 0 then
                    curIdx = curIdx - cellCountX
                end
            elseif direction == "down" then
                if curIdx + cellCountX <= #children then
                    curIdx = curIdx + cellCountX
                end
            elseif direction == "left" then
                if curIdx - 1 > 0 then
                    curIdx = curIdx - 1
                end
            elseif direction == "right" then
                if curIdx + 1 <= #children then
                    curIdx = curIdx + 1
                end
            end
            if temp == curIdx then
                return
            end
            local item = children[curIdx]
            -- 确保item在屏幕内，如果不在则滚动listframe
            if item and isScrollingFrame then
                local itemPos = item.AbsolutePosition
                local itemSize = item.AbsoluteSize
                local listFramePos = listFrame.AbsolutePosition
                local listFrameSize = listFrame.AbsoluteSize
                if itemPos.X < listFramePos.X then
                    listFrame.CanvasPosition = Vector2.new(listFrame.CanvasPosition.X - (listFramePos.X - itemPos.X), listFrame.CanvasPosition.Y)
                elseif itemPos.X + itemSize.X > listFramePos.X + listFrameSize.X then
                    listFrame.CanvasPosition = Vector2.new(listFrame.CanvasPosition.X + (itemPos.X + itemSize.X + cellPaddingX - listFramePos.X - listFrameSize.X), listFrame.CanvasPosition.Y)
                end
                if itemPos.Y < listFramePos.Y then
                    listFrame.CanvasPosition = Vector2.new(listFrame.CanvasPosition.X, listFrame.CanvasPosition.Y - (listFramePos.Y - itemPos.Y))
                elseif itemPos.Y + itemSize.Y > listFramePos.Y + listFrameSize.Y then
                    listFrame.CanvasPosition = Vector2.new(listFrame.CanvasPosition.X, listFrame.CanvasPosition.Y + (itemPos.Y + itemSize.Y + cellPaddingY - listFramePos.Y - listFrameSize.Y))
                end
            end
            return children[curIdx]
        end

        action.KeyEvent.Event:Connect(function(direction)
            local res = getItem(direction)
            if res and cur ~= res then
                cur = res
                local args = table.pack(func(cur))
                if cmd:CanExecute(table.unpack(args)) then
                    cmd:Execute(table.unpack(args))
                end
            end
        end)

        task.spawn(function()
            wait()
            if self._activated then
                self._adapter:_reloadInputs()

                local item = cur
                if item then
                    local args = table.pack(func(item))
                    if cmd:CanExecute(table.unpack(args)) then
                        cmd:Execute(table.unpack(args))
                    end
                end
            end
        end)
        return action
    end
end

