    if cmd then
        local function getChildren()
            local children = {}
            for i, v in pairs(listFrame:GetChildren()) do
                if v:IsA("GuiObject") and v.Visible then
                    table.insert(children, v)
                end
            end
            table.sort(children, function(a, b)
                return a.LayoutOrder < b.LayoutOrder
