                    end
                end
            end
        end)
        return
    end
end

function module:UnbindListDpadAction()
    self:_unbindActionWithName("_ListDpadActionUp")
    self:_unbindActionWithName("_ListDpadActionDown")
    self:_unbindActionWithName("_ListDpadActionLeft")
    self:_unbindActionWithName("_ListDpadActionRight")

    if self._activated then
        self._adapter:_reloadInputs()
    end
end

function module:UnbindListThumbstick1Action()
    self:_unbindActionWithName("_ListThumbstick1Action")

    if self._activated then
        self._adapter:_reloadInputs()
    end
end

function module:EnableGamepadCursor(obj: GuiObject)
    game:GetService("GamepadService"):EnableGamepadCursor(obj)
end

function module:DisableGamepadCursor()
    game:GetService("GamepadService"):DisableGamepadCursor()
end

return module